import { useState, useCallback } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { uploadCVs, runMatching, getDatasetHistory } from "../services/api";
import { useEffect } from "react";

export default function UploadCVs() {
  const { jobId } = useParams();
  const navigate = useNavigate();
  const [files, setFiles] = useState([]);
  const [mode, setMode] = useState("fresh");
  const [uploading, setUploading] = useState(false);
  const [running, setRunning] = useState(false);
  const [uploadResult, setUploadResult] = useState(null);
  const [history, setHistory] = useState([]);
  const [dragging, setDragging] = useState(false);

  useEffect(() => {
    getDatasetHistory(jobId).then(r => setHistory(r.data)).catch(() => {});
  }, [jobId]);

  const onDrop = useCallback((e) => {
    e.preventDefault(); setDragging(false);
    const dropped = Array.from(e.dataTransfer?.files || e.target.files || []);
    setFiles(f => [...f, ...dropped]);
  }, []);

  const upload = async () => {
    if (!files.length) return alert("Please select at least one CV file.");
    setUploading(true);
    try {
      const res = await uploadCVs(jobId, files, mode);
      setUploadResult(res.data);
      setFiles([]);
    } catch (e) { alert("Upload failed. Check backend is running."); }
    finally { setUploading(false); }
  };

  const runAI = async () => {
    setRunning(true);
    try {
      await runMatching(jobId);
      navigate(`/results/${jobId}`);
    } catch (e) { alert("AI matching failed: " + (e.response?.data?.detail || e.message)); }
    finally { setRunning(false); }
  };

  return (
    <div style={{ maxWidth: 720, margin: "0 auto", animation: "fadeUp 0.5s ease" }}>
      <div style={{ marginBottom: 40 }}>
        <div className="badge badge-blue" style={{ marginBottom: 16 }}>Step 2 of 3</div>
        <h1 style={{ fontFamily: "Plus Jakarta Sans", fontWeight: 800, fontSize: 36, color: "var(--text-primary)", marginBottom: 8 }}>
          Upload CV Dataset
        </h1>
        <p style={{ color: "var(--text-secondary)", fontSize: 16 }}>
          Upload the CV files you want the AI to analyse and rank.
        </p>
      </div>

      <div className="card" style={{ padding: 40, display: "grid", gap: 28 }}>

        {/* Upload mode toggle */}
        <div>
          <label className="label">Upload Mode</label>
          <div style={{ display: "flex", gap: 12 }}>
            {["fresh", "append"].map(m => (
              <button key={m} onClick={() => setMode(m)} style={{
                flex: 1, padding: "14px 20px", borderRadius: 10, cursor: "pointer",
                border: `1px solid ${mode === m ? "var(--blue)" : "var(--border)"}`,
                background: mode === m ? "rgba(59,130,246,0.1)" : "var(--navy-3)",
                color: mode === m ? "#60A5FA" : "var(--text-secondary)",
                fontFamily: "Plus Jakarta Sans", fontWeight: 600, fontSize: 14,
                transition: "all 0.2s",
              }}>
                {m === "fresh" ? "🔄 Fresh Upload" : "➕ Append / Update"}
                <div style={{ fontSize: 11, fontWeight: 400, marginTop: 4, opacity: 0.8 }}>
                  {m === "fresh" ? "Replaces all existing CVs" : "Adds new CVs, skips duplicates"}
                </div>
              </button>
            ))}
          </div>
        </div>

        {/* Drop zone */}
        <div
          onDrop={onDrop} onDragOver={e => { e.preventDefault(); setDragging(true); }}
          onDragLeave={() => setDragging(false)}
          onClick={() => document.getElementById("file-input").click()}
          style={{
            border: `2px dashed ${dragging ? "var(--blue)" : "var(--border)"}`,
            borderRadius: 14, padding: "48px 32px", textAlign: "center",
            cursor: "pointer", transition: "all 0.2s",
            background: dragging ? "rgba(59,130,246,0.05)" : "var(--navy-3)",
          }}>
          <input id="file-input" type="file" multiple accept=".pdf,.docx,.txt"
            style={{ display: "none" }} onChange={onDrop} />
          <div style={{ fontSize: 40, marginBottom: 12 }}>📂</div>
          <div style={{ fontFamily: "Plus Jakarta Sans", fontWeight: 600, fontSize: 16, color: "var(--text-primary)", marginBottom: 6 }}>
            Drop CV files here or click to browse
          </div>
          <div style={{ color: "var(--text-muted)", fontSize: 13 }}>
            Supports PDF, DOCX, TXT — upload multiple files at once
          </div>
        </div>

        {/* Selected files */}
        {files.length > 0 && (
          <div style={{ display: "grid", gap: 8 }}>
            <label className="label">{files.length} file{files.length > 1 ? "s" : ""} selected</label>
            <div style={{ maxHeight: 180, overflowY: "auto", display: "grid", gap: 6 }}>
              {files.map((f, i) => (
                <div key={i} style={{
                  display: "flex", alignItems: "center", justifyContent: "space-between",
                  background: "var(--navy-3)", borderRadius: 8, padding: "10px 14px",
                  border: "1px solid var(--border)",
                }}>
                  <span style={{ fontSize: 13, color: "var(--text-secondary)" }}>📄 {f.name}</span>
                  <button onClick={() => setFiles(fs => fs.filter((_, j) => j !== i))}
                    style={{ background: "none", border: "none", color: "var(--text-muted)", cursor: "pointer", fontSize: 16 }}>×</button>
                </div>
              ))}
            </div>
            <button className="btn-primary" onClick={upload} disabled={uploading}>
              {uploading ? "Uploading..." : `Upload ${files.length} CV${files.length > 1 ? "s" : ""}`}
            </button>
          </div>
        )}

        {/* Upload result */}
        {uploadResult && (
          <div style={{
            background: "rgba(20,184,166,0.08)", border: "1px solid rgba(20,184,166,0.2)",
            borderRadius: 12, padding: "16px 20px",
          }}>
            <div style={{ fontFamily: "Plus Jakarta Sans", fontWeight: 600, color: "#2DD4BF", marginBottom: 8 }}>
              ✓ Upload complete
            </div>
            <div style={{ display: "flex", gap: 24, fontSize: 13, color: "var(--text-secondary)" }}>
              <span>Added: <strong style={{ color: "var(--text-primary)" }}>{uploadResult.candidates_added}</strong></span>
              <span>Duplicates skipped: <strong style={{ color: "var(--text-primary)" }}>{uploadResult.duplicates_skipped}</strong></span>
            </div>
          </div>
        )}

        {/* Upload history */}
        {history.length > 0 && (
          <div>
            <label className="label">Upload history</label>
            <div style={{ display: "grid", gap: 6 }}>
              {history.slice(0, 3).map((h, i) => (
                <div key={i} style={{
                  display: "flex", justifyContent: "space-between", alignItems: "center",
                  background: "var(--navy-3)", borderRadius: 8, padding: "10px 14px",
                  border: "1px solid var(--border)", fontSize: 12, color: "var(--text-secondary)",
                }}>
                  <span>{h.upload_mode === "fresh" ? "🔄" : "➕"} {h.upload_mode} — {h.added} added, {h.skipped} skipped</span>
                  <span style={{ color: "var(--text-muted)" }}>{new Date(h.uploaded_at).toLocaleDateString()}</span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Run AI button */}
      <div style={{ marginTop: 24, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <button className="btn-secondary" onClick={() => navigate(`/job-setup`)}>← Back</button>
        <button className="btn-primary" onClick={runAI} disabled={running}
          style={{ minWidth: 200, background: running ? "#1D4ED8" : "var(--blue)" }}>
          {running ? (
            <span>⚙️ Running AI... this may take a moment</span>
          ) : (
            <span>🚀 Run AI Matching →</span>
          )}
        </button>
      </div>
    </div>
  );
}
